#include <Arduino.h>

int Pin = 2;

void setup() {
    Serial.begin(115200);
    pinMode(Pin, OUTPUT);
    digitalWrite(Pin, LOW);
    Serial.println("Listening");
}

void loop() {
    if (Serial.available() > 0) {
        char command = Serial.read();

        if (command == 'F') {
            digitalWrite(Pin, HIGH);
            Serial.println("F received!");
        }
        else if (command == 'C') {
            digitalWrite(Pin, LOW);
            Serial.println("C received!");
        }
    }
}
